import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Introducing Technova","description":"","frontmatter":{},"headers":[],"relativePath":"introducing-technova.md","filePath":"introducing-technova.md"}`),a={name:`introducing-technova.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="introducing-technova" tabindex="-1">Introducing Technova <a class="header-anchor" href="#introducing-technova" aria-label="Permalink to “Introducing Technova”">​</a></h1><h2 id="about-technova" tabindex="-1">About Technova <a class="header-anchor" href="#about-technova" aria-label="Permalink to “About Technova”">​</a></h2><p>Welcome to Technova, a fictional technology retail company that sells a variety of technology products, including laptops, smartphones, monitors, computer accessories, and networking equipment.</p><p>Like any growing business, Technova needs a way to manage its products, customers, orders, payments, suppliers, employees, and inventory.</p><p>To support these operations, Technova uses a relational database built with Microsoft SQL Server.</p><p>Throughout SQL Power Hour, you&#39;ll work with Technova&#39;s database to solve practical problems using SQL. Each topic introduces a set of questions based on the same database, allowing you to apply what you&#39;ve learned in a consistent, realistic environment.</p><h2 id="understanding-the-database" tabindex="-1">Understanding the Database <a class="header-anchor" href="#understanding-the-database" aria-label="Permalink to “Understanding the Database”">​</a></h2><p>Technova&#39;s database consists of 11 tables. Each table represents a particular entity or concept within the business.</p><p>The tables are related through primary keys and foreign keys, allowing us to retrieve and analyze information across the database.</p><p>The following sections describe each table, its columns, and the information stored in each column.</p><p><strong>Note:</strong> <code>PK</code> identifies a primary key, while <code>FK</code> identifies a foreign key referencing another table. These labels are included in the descriptions for clarity.</p><p><strong>Nullability:</strong> A column marked <code>NULL</code> in its data type may contain missing values. Every other column is required and always has a value.</p><h3 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to “Naming Conventions”">​</a></h3><p>All table and column names use <code>snake_case</code>: lowercase words separated by underscores, such as <code>order_items</code> and <code>customer_id</code>. Table names are plural.</p><p>Because the names are lowercase, you can write them in your queries without double quotes:</p><div class="language-sql"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customer_id, first_name</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customers;</span></span></code></pre></div><p>To inspect a table&#39;s structure at any time in <code>psql</code>, use <code>\\d</code> followed by the table name, for example <code>\\d products</code>. Use <code>\\dt</code> to list all tables.</p><hr><h1 id="_1-categories" tabindex="-1">1. categories <a class="header-anchor" href="#_1-categories" aria-label="Permalink to “1. categories”">​</a></h1><p>The <code>categories</code> table stores the categories into which Technova organizes its products.</p><p>Examples include Laptops, Smartphones, Monitors, Accessories, and Networking Equipment.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>category_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each category.</td></tr><tr><td>category_name</td><td>VARCHAR(100)</td><td>Name of the product category.</td></tr><tr><td>description</td><td>VARCHAR(255), NULL</td><td>Brief description of the category, if provided.</td></tr></tbody></table><h1 id="_2-suppliers" tabindex="-1">2. suppliers <a class="header-anchor" href="#_2-suppliers" aria-label="Permalink to “2. suppliers”">​</a></h1><p>The <code>suppliers</code> table stores information about the companies that supply products to Technova.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>supplier_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each supplier.</td></tr><tr><td>supplier_name</td><td>VARCHAR(150)</td><td>Name of the supplier company.</td></tr><tr><td>contact_email</td><td>VARCHAR(150)</td><td>Supplier&#39;s contact email address.</td></tr><tr><td>country</td><td>VARCHAR(100), NULL</td><td>Country in which the supplier operates, if known.</td></tr></tbody></table><h1 id="_3-products" tabindex="-1">3. products <a class="header-anchor" href="#_3-products" aria-label="Permalink to “3. products”">​</a></h1><p>The <code>products</code> table stores information about the products Technova offers for sale.</p><p>Each product belongs to a category and has a primary supplier.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>product_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each product.</td></tr><tr><td>product_name</td><td>VARCHAR(150)</td><td>Name of the product.</td></tr><tr><td>category_id</td><td>INTEGER</td><td>Foreign key referencing <code>categories</code>. Identifies the product&#39;s category.</td></tr><tr><td>supplier_id</td><td>INTEGER</td><td>Foreign key referencing <code>suppliers</code>. Identifies the product&#39;s primary supplier.</td></tr><tr><td>unit_price</td><td>NUMERIC(10,2)</td><td>Current selling price of one unit of the product.</td></tr><tr><td>cost_price</td><td>NUMERIC(10,2)</td><td>Cost to Technova of acquiring one unit of the product.</td></tr><tr><td>created_at</td><td>DATE</td><td>Date the product was added to Technova&#39;s catalog.</td></tr></tbody></table><h1 id="_4-customers" tabindex="-1">4. customers <a class="header-anchor" href="#_4-customers" aria-label="Permalink to “4. customers”">​</a></h1><p>The <code>customers</code> table stores information about people who purchase products from Technova.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>customer_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each customer.</td></tr><tr><td>first_name</td><td>VARCHAR(100)</td><td>Customer&#39;s first name.</td></tr><tr><td>last_name</td><td>VARCHAR(100)</td><td>Customer&#39;s last name.</td></tr><tr><td>email</td><td>VARCHAR(150)</td><td>Customer&#39;s email address. Unique: no two customers share an email.</td></tr><tr><td>city</td><td>VARCHAR(100)</td><td>City in which the customer resides.</td></tr><tr><td>country</td><td>VARCHAR(100)</td><td>Country in which the customer resides.</td></tr><tr><td>registered_at</td><td>DATE</td><td>Date the customer registered with Technova.</td></tr></tbody></table><h1 id="_5-departments" tabindex="-1">5. departments <a class="header-anchor" href="#_5-departments" aria-label="Permalink to “5. departments”">​</a></h1><p>The <code>departments</code> table stores information about Technova&#39;s organizational departments.</p><p>Examples include Sales, Customer Support, Logistics, IT, and Finance.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>department_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each department.</td></tr><tr><td>department_name</td><td>VARCHAR(100)</td><td>Name of the department.</td></tr><tr><td>location</td><td>VARCHAR(100), NULL</td><td>Location associated with the department, if any.</td></tr></tbody></table><h1 id="_6-employees" tabindex="-1">6. employees <a class="header-anchor" href="#_6-employees" aria-label="Permalink to “6. employees”">​</a></h1><p>The <code>employees</code> table stores information about people working at Technova.</p><p>Each employee belongs to a department and may be assigned responsibility for handling customer orders.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>employee_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each employee.</td></tr><tr><td>first_name</td><td>VARCHAR(100)</td><td>Employee&#39;s first name.</td></tr><tr><td>last_name</td><td>VARCHAR(100)</td><td>Employee&#39;s last name.</td></tr><tr><td>department_id</td><td>INTEGER</td><td>Foreign key referencing <code>departments</code>. Identifies the employee&#39;s department.</td></tr><tr><td>hire_date</td><td>DATE</td><td>Date the employee joined Technova.</td></tr><tr><td>job_title</td><td>VARCHAR(100)</td><td>Employee&#39;s job title.</td></tr></tbody></table><h1 id="_7-orders" tabindex="-1">7. orders <a class="header-anchor" href="#_7-orders" aria-label="Permalink to “7. orders”">​</a></h1><p>The <code>orders</code> table stores information about orders placed by Technova&#39;s customers.</p><p>Each order belongs to a customer and may be assigned to an employee.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>order_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each order.</td></tr><tr><td>customer_id</td><td>INTEGER</td><td>Foreign key referencing <code>customers</code>. Identifies the customer who placed the order.</td></tr><tr><td>employee_id</td><td>INTEGER, NULL</td><td>Foreign key referencing <code>employees</code>. Identifies the employee responsible for the order, if assigned.</td></tr><tr><td>order_date</td><td>DATE</td><td>Date the order was placed.</td></tr><tr><td>order_status</td><td>VARCHAR(30)</td><td>Current status of the order. One of: <code>Pending</code>, <code>Processing</code>, <code>Shipped</code>, <code>Delivered</code>, or <code>Cancelled</code>.</td></tr></tbody></table><h1 id="_8-order-items" tabindex="-1">8. order_items <a class="header-anchor" href="#_8-order-items" aria-label="Permalink to “8. order_items”">​</a></h1><p>The <code>order_items</code> table stores the individual products included in each order.</p><p>An order can contain multiple products, and a product can appear in multiple orders. This table records the relationship between orders and products.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>order_item_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each order item.</td></tr><tr><td>order_id</td><td>INTEGER</td><td>Foreign key referencing <code>orders</code>. Identifies the order containing the item.</td></tr><tr><td>product_id</td><td>INTEGER</td><td>Foreign key referencing <code>products</code>. Identifies the product purchased.</td></tr><tr><td>quantity</td><td>INTEGER</td><td>Number of units of the product included in the order. Always greater than zero.</td></tr><tr><td>unit_price</td><td>NUMERIC(10,2)</td><td>Price per unit at the time the order was placed.</td></tr></tbody></table><p><strong>Important:</strong> The <code>unit_price</code> in this table represents the historical purchase price, whereas <code>products.unit_price</code> represents the current selling price. These values may differ.</p><h1 id="_9-payments" tabindex="-1">9. payments <a class="header-anchor" href="#_9-payments" aria-label="Permalink to “9. payments”">​</a></h1><p>The <code>payments</code> table records payments associated with customer orders.</p><p>An order may have multiple payment records, allowing Technova to track payments made through separate transactions.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>payment_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each payment record.</td></tr><tr><td>order_id</td><td>INTEGER</td><td>Foreign key referencing <code>orders</code>. Identifies the order associated with the payment.</td></tr><tr><td>payment_date</td><td>DATE</td><td>Date the payment was recorded.</td></tr><tr><td>amount</td><td>NUMERIC(10,2)</td><td>Monetary amount of the payment.</td></tr><tr><td>payment_method</td><td>VARCHAR(30)</td><td>Method used to make the payment. One of: <code>Card</code>, <code>PayPal</code>, or <code>Bank Transfer</code>.</td></tr><tr><td>payment_status</td><td>VARCHAR(30)</td><td>Status of the payment. One of: <code>Pending</code>, <code>Completed</code>, or <code>Failed</code>.</td></tr></tbody></table><h1 id="_10-warehouses" tabindex="-1">10. warehouses <a class="header-anchor" href="#_10-warehouses" aria-label="Permalink to “10. warehouses”">​</a></h1><p>The <code>warehouses</code> table stores information about the locations where Technova keeps its inventory.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>warehouse_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each warehouse.</td></tr><tr><td>warehouse_name</td><td>VARCHAR(100)</td><td>Name of the warehouse.</td></tr><tr><td>city</td><td>VARCHAR(100)</td><td>City in which the warehouse is located.</td></tr><tr><td>country</td><td>VARCHAR(100)</td><td>Country in which the warehouse is located.</td></tr></tbody></table><h1 id="_11-inventory" tabindex="-1">11. inventory <a class="header-anchor" href="#_11-inventory" aria-label="Permalink to “11. inventory”">​</a></h1><p>The <code>inventory</code> table tracks the quantity of each product stored at individual warehouses.</p><p>A product may be stored in multiple warehouses, and each warehouse may store multiple products. Each product has at most one inventory record per warehouse.</p><table tabindex="0"><thead><tr><th>Column Name</th><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>inventory_id</td><td>INTEGER</td><td>Primary key. Uniquely identifies each inventory record.</td></tr><tr><td>product_id</td><td>INTEGER</td><td>Foreign key referencing <code>products</code>. Identifies the product being tracked.</td></tr><tr><td>warehouse_id</td><td>INTEGER</td><td>Foreign key referencing <code>warehouses</code>. Identifies the warehouse storing the product.</td></tr><tr><td>quantity_in_stock</td><td>INTEGER</td><td>Number of units currently available in the warehouse.</td></tr><tr><td>reorder_level</td><td>INTEGER</td><td>Stock threshold below which replenishment should be considered.</td></tr><tr><td>last_updated</td><td>DATE</td><td>Date the inventory record was last updated.</td></tr></tbody></table><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Technova&#39;s database contains 11 tables covering four main areas of the business:</p><table tabindex="0"><thead><tr><th>Area</th><th>Tables</th><th>Purpose</th></tr></thead><tbody><tr><td>Product Catalog</td><td><code>categories</code>, <code>suppliers</code>, <code>products</code></td><td>Organizes products and their suppliers.</td></tr><tr><td>Customers &amp; Sales</td><td><code>customers</code>, <code>orders</code>, <code>order_items</code>, <code>payments</code></td><td>Tracks customers, purchases, and payments.</td></tr><tr><td>Inventory</td><td><code>warehouses</code>, <code>inventory</code></td><td>Tracks stock across warehouse locations.</td></tr><tr><td>Company Operations</td><td><code>departments</code>, <code>employees</code></td><td>Represents Technova&#39;s internal organization.</td></tr></tbody></table><p>As you work through SQL Power Hour, you&#39;ll use these tables to practise retrieving, filtering, sorting, grouping, joining, and analyzing data.</p><p>The same database will support increasingly challenging exercises, allowing you to build on your existing knowledge and develop stronger SQL problem-solving skills.</p>`,66)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};